head.b:skin:
/*
=====================================================================
  TEMPLATE MARKET - Blogger theme for selling / showcasing templates,
  themes, plugins or any digital products (single file).

  CUSTOMIZE: Blogger > Theme > Customize changes the colours below.
  LAYOUT:    Blogger > Layout lets you edit the hero card, announcement
             bar, ad slots and the "Why choose us" band.
  CONTENT:   Edit "var CFG" at the bottom of this file.
=====================================================================

<Variable name="brand.color" description="Brand colour (buttons, links)" type="color" default="#2563eb" value="#2563eb"/>
<Variable name="brand2.color" description="Accent colour" type="color" default="#7c5cfc" value="#7c5cfc"/>
<Variable name="hero1.color" description="Hero gradient - top" type="color" default="#3f6ef5" value="#3f6ef5"/>
<Variable name="hero2.color" description="Hero gradient - bottom" type="color" default="#8f7bff" value="#8f7bff"/>
<Variable name="text.color" description="Text colour" type="color" default="#1f2937" value="#1f2937"/>
<Variable name="bg.color" description="Page background" type="color" default="#f3f4f8" value="#f3f4f8"/>
<Variable name="card.color" description="Card background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="footer.color" description="Footer background" type="color" default="#202225" value="#202225"/>
<Variable name="good.color" description="Demo / success colour" type="color" default="#16a34a" value="#16a34a"/>
<Variable name="star.color" description="Star rating colour" type="color" default="#f5a623" value="#f5a623"/>
*/

:root{
  --brand:$(brand.color);
  --brand2:$(brand2.color);
  --hero1:$(hero1.color);
  --hero2:$(hero2.color);
  --ink:$(text.color);
  --bg:$(bg.color);
  --card:$(card.color);
  --foot:$(footer.color);
  --good:$(good.color);
  --star:$(star.color);
  --mut:#6b7280;
  --line:#e4e7ee;
  --soft:#f7f8fc;
  --r:14px;
  --sh:0 1px 2px rgba(20,30,70,.05),0 6px 20px rgba(20,30,70,.07);
  --sh-h:0 18px 40px rgba(20,30,70,.18);
  --font:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;
  --serif:'Playfair Display',Georgia,'Times New Roman',serif;
  --ease:cubic-bezier(.2,.8,.2,1);
  --cols:3;
}
[data-theme='dark']{
  --bg:#0c111c;
  --card:#141b2b;
  --ink:#e8edf8;
  --mut:#98a4bb;
  --line:#222d45;
  --soft:#101726;
  --sh:0 1px 2px rgba(0,0,0,.4),0 6px 20px rgba(0,0,0,.3);
  --sh-h:0 18px 40px rgba(0,0,0,.55);
}

/* ---------- base ---------- */
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:84px}
body{margin:0;font-family:var(--font);background:var(--bg);color:var(--ink);line-height:1.55;font-size:15px;-webkit-font-smoothing:antialiased;transition:background .3s,color .3s}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4,p,ul{margin:0}
ul{padding:0;list-style:none}
button,input{font-family:inherit}
button{cursor:pointer;border:0;background:none;color:inherit}
:focus-visible{outline:3px solid #fbbf24;outline-offset:2px;border-radius:6px}
.wrap{max-width:1240px;margin:0 auto;padding:0 20px}
.skip{position:fixed;left:12px;top:-60px;z-index:999;background:#fbbf24;color:#111;font-weight:700;padding:10px 16px;border-radius:8px;transition:top .2s}
.skip:focus{top:12px}
#rp{position:fixed;top:0;left:0;height:3px;width:0;background:linear-gradient(90deg,#fbbf24,#ff6a3d);z-index:600;transition:width .1s linear}
.tpl{display:none!important}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}

/* ---------- announcement bar ---------- */
.ann{background:linear-gradient(90deg,var(--brand),var(--brand2));color:#fff;font-size:13px;font-weight:600;text-align:center;padding:8px 0}
.ann a{text-decoration:underline}

/* ---------- header ---------- */
.site-header{position:sticky;top:0;z-index:300;background:var(--card);border-bottom:1px solid var(--line);transition:box-shadow .3s}
.site-header.scrolled{box-shadow:0 10px 30px rgba(20,30,70,.14)}
.bar{display:flex;align-items:center;gap:22px;height:66px}
.logo{display:flex;align-items:center;gap:8px;flex-shrink:0}
.logo svg{width:34px;height:34px;animation:popIn .8s cubic-bezier(.2,1.4,.4,1) both}
.logo .lt{font:700 22px/1 var(--font);letter-spacing:-.4px}
.logo small{display:block;text-align:right;font-size:10px;color:var(--mut);margin-top:2px}
.nav{display:flex;align-items:center;gap:2px;margin-left:auto;height:100%}
.nv{position:relative;height:100%;display:flex;align-items:center}
.nv>a{position:relative;display:flex;align-items:center;gap:5px;height:100%;padding:0 16px;font-weight:500;font-size:14.5px;color:var(--ink);transition:color .2s}
.nv>a svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.4;transition:transform .25s}
.nv>a::after{content:'';position:absolute;left:16px;right:16px;bottom:-1px;height:3px;border-radius:3px 3px 0 0;background:var(--brand);transform:scaleX(0);transition:transform .3s var(--ease)}
.nv:hover>a,.nv>a.cur{color:var(--brand)}
.nv:hover>a::after,.nv>a.cur::after{transform:scaleX(1)}
.nv:hover>a svg{transform:rotate(180deg)}
.sub{position:absolute;top:100%;left:0;min-width:220px;background:var(--card);border:1px solid var(--line);border-radius:0 0 14px 14px;box-shadow:var(--sh-h);padding:8px;opacity:0;visibility:hidden;transform:translateY(8px);transition:all .25s var(--ease)}
.nv:hover .sub,.nv:focus-within .sub{opacity:1;visibility:visible;transform:none}
.sub a{display:block;padding:9px 12px;border-radius:8px;font-size:14px;font-weight:500}
.sub a:hover{background:var(--soft);color:var(--brand)}
.actions{display:flex;align-items:center;gap:10px;margin-left:8px}
.aff{display:inline-flex;align-items:center;gap:8px;background:#e6efff;color:#2563eb;font-weight:600;font-size:14px;padding:9px 18px;border-radius:9px;transition:transform .2s,box-shadow .2s,background .2s}
.aff svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2}
.aff:hover{background:var(--brand);color:#fff;transform:translateY(-2px);box-shadow:0 8px 18px rgba(37,99,235,.35)}
[data-theme='dark'] .aff{background:#1a2a52;color:#8db4ff}
.sqbtn{width:42px;height:42px;border-radius:10px;background:#eef0f5;display:grid;place-items:center;color:var(--ink);transition:background .2s,transform .2s}
[data-theme='dark'] .sqbtn{background:#1c2639}
.sqbtn:hover{background:var(--brand);color:#fff;transform:translateY(-2px)}
.sqbtn svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.burger{display:none}

.drawer{position:fixed;inset:0 0 0 auto;width:min(330px,88vw);background:var(--card);color:var(--ink);z-index:420;transform:translateX(105%);visibility:hidden;transition:transform .35s var(--ease);padding:78px 18px 24px;overflow:auto;box-shadow:var(--sh-h)}
.drawer.open{transform:none;visibility:visible}
.drawer a{display:block;padding:13px 12px;font-weight:600;border-bottom:1px solid var(--line);border-radius:8px}
.drawer a:hover{background:var(--soft);color:var(--brand)}
.drawer .ds a{padding-left:28px;font-weight:500;color:var(--mut);font-size:14px}
.drawer .x{position:absolute;top:14px;right:14px}
.scrim{position:fixed;inset:0;background:rgba(8,14,34,.6);backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:opacity .3s;z-index:410}
.scrim.open{opacity:1;pointer-events:auto}
.search-ov{position:fixed;inset:0;z-index:500;background:rgba(18,28,70,.96);padding:80px 20px 20px;overflow:auto;opacity:0;pointer-events:none;transition:opacity .3s}
.search-ov.open{opacity:1;pointer-events:auto}
.search-in{width:min(760px,100%);margin:0 auto;transform:translateY(20px);transition:transform .35s var(--ease)}
.search-ov.open .search-in{transform:none}
.search-in input{width:100%;font:600 clamp(20px,4vw,30px) var(--font);padding:14px 4px;color:#fff;background:none;border:0;border-bottom:3px solid #fbbf24;outline:0}
.search-in input::placeholder{color:rgba(255,255,255,.45)}
.search-ov .x{position:absolute;top:18px;right:18px;color:#fff;background:rgba(255,255,255,.12)}
.sres{margin-top:18px;display:grid;gap:4px}
.sres a,.sdrop a{display:flex;gap:14px;align-items:center;padding:10px;border-radius:10px;transition:background .2s}
.sres a{color:#fff}.sres a:hover{background:rgba(255,255,255,.1)}
.sres img,.sdrop img{width:64px;height:44px;object-fit:cover;object-position:top;border-radius:6px;flex-shrink:0;background:var(--line)}
.sres span,.sdrop span{font-weight:600;font-size:14px;flex:1;min-width:0}
.sres b,.sdrop b{font-size:13px;color:#fbbf24}
.sdrop b{color:var(--brand)}
.sres em,.sdrop em{display:block;padding:10px;font-style:normal;font-size:13px;color:#b9c6e6}
.sdrop em{color:var(--mut)}
.circle{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;transition:background .2s,transform .2s}
.circle:hover{transform:rotate(90deg)}
.circle svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}

/* ---------- hero ---------- */
.hero{display:none;position:relative;color:#fff;overflow:hidden;isolation:isolate;background:linear-gradient(180deg,var(--hero1),var(--hero2))}
.is-home .hero{display:block}
.hero .blob{position:absolute;border-radius:50%;filter:blur(2px);z-index:-1;animation:blob 14s ease-in-out infinite}
.hero .b1{width:380px;height:380px;left:-110px;top:-120px;background:rgba(255,255,255,.12)}
.hero .b2{width:260px;height:260px;right:30%;top:40px;background:rgba(251,191,36,.18);animation-delay:-5s}
.hero .b3{width:520px;height:520px;right:-180px;bottom:-240px;background:rgba(255,255,255,.1);animation-delay:-9s}
.hero .spark{position:absolute;z-index:-1;color:rgba(255,255,255,.7);font-size:18px;animation:twinkle 3s ease-in-out infinite}
.hero-in{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:44px;align-items:center;padding-top:62px;padding-bottom:150px}
.hero h1{font:800 clamp(28px,3.6vw,40px)/1.22 var(--font);letter-spacing:-.8px;animation:rise .8s var(--ease) both}
.hero .hl{display:inline;margin-top:14px;font-size:14.5px;line-height:2;color:#1a1a1a;background:#fde047;padding:2px 6px;box-decoration-break:clone;-webkit-box-decoration-break:clone;animation:rise .8s .1s var(--ease) both}
.hero .hlw{display:block;margin-top:14px;animation:rise .8s .1s var(--ease) both}
.hsearch{position:relative;display:flex;align-items:center;background:#fff;border-radius:10px;margin-top:20px;padding:0 8px 0 18px;height:56px;box-shadow:0 14px 34px rgba(18,28,90,.28);max-width:520px;animation:rise .8s .2s var(--ease) both}
.hsearch input{flex:1;min-width:0;border:0;outline:0;background:none;font-size:14.5px;color:#1f2937}
.hsearch input::placeholder{color:#8a93a8}
.hsearch button{width:42px;height:42px;display:grid;place-items:center;color:#8a93a8;transition:color .2s,transform .2s}
.hsearch button:hover{color:var(--brand);transform:scale(1.12)}
.hsearch svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
.sdrop{position:absolute;top:calc(100% + 10px);left:0;right:0;background:var(--card);color:var(--ink);border:1px solid var(--line);border-radius:14px;box-shadow:var(--sh-h);padding:6px;display:none;z-index:50}
.sdrop.show{display:block}
.sdrop a:hover{background:var(--soft)}
.popular{margin-top:16px;font-size:12.5px;color:#e9eeff;animation:rise .8s .3s var(--ease) both}
.popular a{text-decoration:underline;text-underline-offset:3px;margin-left:4px}
.popular a:hover{color:#fde047}
.hero-r{animation:rise .9s .25s var(--ease) both}
.promo{position:relative;display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:10px;background:#fff;color:#111827;border-radius:14px;padding:28px 26px;box-shadow:0 24px 60px rgba(18,28,90,.32);overflow:hidden}
.promo h3{font:700 22px/1.25 var(--font)}
.promo p{font-size:11.5px;line-height:1.5;margin:10px 0 16px;color:#374151;font-weight:500}
.pbtn{display:inline-block;background:#111827;color:#fff;font-weight:700;font-size:12.5px;padding:10px 20px;border-radius:5px;transition:transform .25s,box-shadow .25s,background .25s}
.pbtn:hover{background:var(--brand);transform:translateY(-3px);box-shadow:0 10px 20px rgba(37,99,235,.4)}
.illus{width:100%;max-width:260px;justify-self:end;animation:floaty 6s ease-in-out infinite}
.illus .blink{animation:blink 1s steps(2) infinite}
.illus .fl{animation:floaty 4s ease-in-out infinite}
.wave{position:absolute;left:0;bottom:-1px;width:100%;height:120px;display:block;z-index:1}
.wave.back{height:140px;width:200%;animation:waveMove 18s linear infinite}
.wave.front{height:110px}

/* ---------- section scaffolding ---------- */
.sec{padding:34px 0 10px;position:relative;z-index:2}
.sec-h{text-align:center;margin-bottom:22px}
.sec-h h2{font:700 clamp(22px,2.6vw,27px)/1.25 var(--font);letter-spacing:-.4px}
.sec-h p{font-size:12.5px;color:var(--mut);margin-top:6px}
.pills{display:flex;gap:12px;overflow-x:auto;padding:6px 4px 14px;scroll-snap-type:x proximity;scrollbar-width:thin;scrollbar-color:#c3c8d6 transparent;-webkit-overflow-scrolling:touch}
.pills::-webkit-scrollbar{height:4px}
.pills::-webkit-scrollbar-thumb{background:#c3c8d6;border-radius:4px}
.pill{flex-shrink:0;scroll-snap-align:start;border:1.5px solid var(--line);background:var(--card);color:var(--mut);font-size:14px;font-weight:500;padding:10px 24px;border-radius:999px;transition:all .25s var(--ease)}
.pill:hover{color:var(--brand);border-color:var(--brand);transform:translateY(-2px)}
.pill.on{color:var(--brand);border:2px solid #7ea6ff;box-shadow:0 0 0 4px rgba(37,99,235,.12);font-weight:600}

/* ---------- product cards ---------- */
.pgrid{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));gap:24px 22px;margin-top:14px;transition:opacity .25s}
.pgrid.fade{opacity:.25}
.pcard{position:relative;background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden;box-shadow:var(--sh);transition:box-shadow .3s,border-color .3s}
.pcard:hover{box-shadow:var(--sh-h);border-color:#cdd6ee}
.pv{position:relative;display:block;aspect-ratio:16/9.6;overflow:hidden;background:linear-gradient(135deg,var(--g1,#f6d5f7),var(--g2,#c9e4ff));color:var(--fg,#2a2a3c)}
.pv::before{content:'';position:absolute;width:60%;aspect-ratio:1;border-radius:50%;right:-15%;top:-25%;background:rgba(255,255,255,.35);animation:blob 12s ease-in-out infinite}
.price{position:absolute;left:10px;top:10px;z-index:3;background:rgba(55,65,81,.55);backdrop-filter:blur(4px);color:#fff;font-size:12px;font-weight:700;padding:5px 10px;border-radius:7px}
.price.free{background:rgba(22,163,74,.9)}
.tag{position:absolute;left:10px;top:42px;z-index:3;background:#ef4444;color:#fff;font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;padding:3px 8px;border-radius:5px}
.pname{position:absolute;top:12px;left:0;right:0;z-index:2;text-align:center;font:700 clamp(20px,2vw,25px)/1.1 var(--serif);padding:0 70px}
.frame{position:absolute;left:9%;right:9%;top:32%;bottom:-8%;z-index:1;border-radius:10px 10px 0 0;overflow:hidden;background:#fff;border:5px solid #2b2f3a;border-bottom:0;box-shadow:0 14px 28px rgba(20,30,70,.28);transition:transform .6s var(--ease)}
.frame img{width:100%;height:100%;object-fit:cover;object-position:top}
.pcard:hover .frame{transform:translateY(-8px) scale(1.03)}
.vd{position:absolute;left:50%;top:50%;z-index:4;transform:translate(-50%,-40%) scale(.9);background:rgba(34,38,48,.78);color:#fff;font-weight:600;font-size:14px;padding:10px 26px;border-radius:8px;opacity:0;transition:all .3s var(--ease);white-space:nowrap}
.pcard:hover .vd,.pv:focus-visible .vd{opacity:1;transform:translate(-50%,-50%) scale(1)}
.pb{padding:12px 14px 12px}
.pb h3{font:600 14px/1.4 var(--font);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pb h3 a:hover{color:var(--brand)}
.pr{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-top:8px}
.rt{display:grid;gap:3px;min-width:0}
.rt .l1{display:flex;align-items:center;gap:6px}
.rt small{font-size:11px;color:var(--mut)}
.st{font-size:12px;letter-spacing:1px;line-height:1;background:linear-gradient(90deg,var(--star) calc(var(--r)*20%),#d3d8e4 0);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.pa{display:flex;gap:8px;flex-shrink:0}
.cart,.demo{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;border:1px solid var(--line);border-radius:6px;font-size:12px;font-weight:600;transition:all .25s var(--ease);background:var(--card)}
.cart{width:34px;color:var(--good)}
.demo{padding:0 14px;color:var(--good)}
.cart svg,.demo svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cart:hover,.demo:hover{background:var(--good);border-color:var(--good);color:#fff;transform:translateY(-2px)}
.more-wrap{display:flex;justify-content:center;margin:26px 0 8px}
.mbtn{display:inline-flex;align-items:center;gap:8px;background:#e6e8ee;color:#4b5563;font-weight:500;font-size:13.5px;padding:11px 28px;border-radius:6px;transition:all .25s var(--ease)}
[data-theme='dark'] .mbtn{background:#1c2639;color:#cbd5e8}
.mbtn:hover{background:var(--brand);color:#fff;transform:translateY(-2px);box-shadow:0 10px 22px rgba(37,99,235,.3)}
.mbtn .sp{width:14px;height:14px;border:2px solid currentColor;border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite;display:none}
.mbtn.loading .sp{display:inline-block}
.empty{grid-column:1/-1;padding:26px;text-align:center;color:var(--mut);border:1px dashed var(--line);border-radius:12px;font-size:14px}

/* best sellers */
.best{background:#eceef4;border-radius:6px;padding:16px 16px 18px;margin-top:30px}
[data-theme='dark'] .best{background:#101726}
.best h2{font:600 17px var(--font);margin:0 0 14px 4px}
.best .pgrid{margin-top:0}
.best .pv{aspect-ratio:16/10}
.best .by{font-size:11px;color:var(--mut);margin-top:6px}
.best .tg{font-size:11px;color:var(--mut);margin-top:2px}

/* ad slots */
.adslot{margin:26px auto 0;text-align:center}
.adslot .widget-content{min-height:0}

/* why choose */
.why{margin-top:30px;border-radius:8px;padding:18px 22px 22px;background:linear-gradient(110deg,#e4ecff,#eadfff 55%,#e0f0ff);position:relative;overflow:hidden}
[data-theme='dark'] .why{background:linear-gradient(110deg,#14213f,#1d1840 55%,#10243a)}
.why h2{display:flex;align-items:center;justify-content:center;gap:12px;font:800 clamp(19px,2.4vw,23px) var(--font);color:#1e3a8a;text-align:center;flex-wrap:wrap}
[data-theme='dark'] .why h2{color:#a8c2ff}
.why h2::before,.why h2::after{content:'';height:3px;width:46px;border-radius:3px;background:linear-gradient(90deg,var(--brand),transparent);animation:slideX 2.4s ease-in-out infinite alternate}
.why h2::after{transform:scaleX(-1)}
.why .sub2{text-align:center;font-size:12.5px;color:#3b4a74;margin:8px 0 18px}
[data-theme='dark'] .why .sub2{color:#9fb0d8}
.wgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0}
.wi{display:flex;align-items:center;gap:14px;padding:6px 18px;border-left:1px solid rgba(37,99,235,.18);transition:transform .3s var(--ease)}
.wi:first-child{border-left:0}
.wi:hover{transform:translateY(-4px)}
.wi .ic{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;flex-shrink:0;box-shadow:0 8px 18px rgba(20,30,70,.25);color:#fff}
.wi .ic svg{width:24px;height:24px;fill:currentColor}
.wi h4{font:700 14px var(--font);color:#1d4ed8}
[data-theme='dark'] .wi h4{color:#8db4ff}
.wi p{font-size:12px;line-height:1.4;color:#334155}
[data-theme='dark'] .wi p{color:#a9b6d3}

/* ---------- archive + static pages ---------- */
.inner{padding:28px 0 30px}
.page-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:28px;align-items:start}
.page-grid.nos{grid-template-columns:minmax(0,1fr)}
.side{display:grid;gap:18px;position:sticky;top:90px}
.side .widget{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:18px;box-shadow:var(--sh)}
.side .widget h3{font:700 16px var(--font);margin-bottom:10px}
.arch-title{font:800 clamp(24px,3vw,30px)/1.2 var(--font);letter-spacing:-.5px;margin-bottom:6px}
.arch-sub{color:var(--mut);font-size:13.5px;margin-bottom:18px}
.ssr{background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden}
.ssr img{width:100%;aspect-ratio:16/10;object-fit:cover;object-position:top}
.ssr h2{font:600 15px/1.4 var(--font);padding:12px 14px}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:24px}
.btn{display:inline-flex;align-items:center;gap:8px;background:var(--brand);color:#fff;font-weight:700;font-size:14px;padding:11px 26px;border-radius:9px;transition:transform .25s var(--ease),box-shadow .25s,filter .25s}
.btn:hover{transform:translateY(-2px);box-shadow:0 10px 22px rgba(37,99,235,.35);filter:brightness(1.08)}
.btn.ghost{background:var(--card);color:var(--brand);border:1px solid var(--line)}
.crumbs{display:flex;flex-wrap:wrap;gap:6px;font-size:12.5px;color:var(--mut);margin-bottom:12px}
.crumbs a:hover{color:var(--brand)}
.crumbs .sep{opacity:.6}
.page-art{padding:clamp(18px,4vw,36px)}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.chip{display:inline-block;background:#e6efff;color:#2563eb;font-size:11.5px;font-weight:700;padding:4px 11px;border-radius:999px;transition:all .2s}
[data-theme='dark'] .chip{background:#1a2a52;color:#8db4ff}
.chip:hover{background:var(--brand);color:#fff}
.post-title{font:800 clamp(26px,4vw,38px)/1.2 var(--font);letter-spacing:-.6px;margin:6px 0 12px}
.pd{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:26px;align-items:start}
.pd-meta{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:13px;color:var(--mut);margin-bottom:18px}
.pframe{border-radius:14px;overflow:hidden;background:linear-gradient(135deg,#dfe9ff,#efe2ff);padding:26px 26px 0;box-shadow:var(--sh);margin-bottom:22px;position:relative}
.pframe .win{background:#fff;border-radius:10px 10px 0 0;overflow:hidden;box-shadow:0 18px 40px rgba(20,30,70,.3);border:1px solid #e1e5f0;border-bottom:0}
.pframe .tb{display:flex;gap:6px;padding:10px 12px;background:#f1f3f9}
.pframe .tb i{width:10px;height:10px;border-radius:50%;background:#ff5f57}
.pframe .tb i:nth-child(2){background:#febc2e}.pframe .tb i:nth-child(3){background:#28c840}
.pframe img{width:100%;height:auto;max-height:520px;object-fit:cover;object-position:top}
.post-body{font-size:16.5px;line-height:1.85;overflow-wrap:anywhere}
.post-body.card{padding:clamp(18px,3vw,30px)}
.post-body img{max-width:100%;height:auto;border-radius:10px}
.post-body iframe{max-width:100%;border:0}
.post-body iframe[src*='youtube']{width:100%;height:auto;aspect-ratio:16/9;border-radius:12px}
.post-body h2,.post-body h3{font-family:var(--font);margin:1.6em 0 .6em;line-height:1.3;letter-spacing:-.3px}
.post-body a{color:var(--brand);text-decoration:underline;text-underline-offset:3px}
.post-body ul{list-style:disc;padding-left:1.4em}
.post-body ol{padding-left:1.4em}
.post-body blockquote{margin:1.4em 0;padding:12px 20px;border-left:4px solid #fbbf24;background:var(--soft);border-radius:0 10px 10px 0}
.post-body pre{background:#0b1730;color:#dbe6ff;padding:16px;border-radius:10px;overflow:auto}
.post-body table{max-width:100%;display:block;overflow:auto;border-collapse:collapse}
.post-body th,.post-body td{border:1px solid var(--line);padding:8px 12px}
.post-body .separator,.post-body .tr-caption-container{text-align:center!important}
.pd-side{position:sticky;top:90px;display:grid;gap:16px}
.bb{padding:22px}
.bp{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.bp .now{font:800 34px/1 var(--font);letter-spacing:-1px}
.bp .old{color:var(--mut);font-size:16px}
.bp .off{background:#fee2e2;color:#dc2626;font-weight:700;font-size:12px;padding:3px 8px;border-radius:6px}
.bb .rt{margin:12px 0 18px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.bbtn{display:flex;align-items:center;justify-content:center;gap:9px;width:100%;padding:13px 18px;border-radius:10px;font-weight:700;font-size:15px;transition:transform .25s var(--ease),box-shadow .25s,filter .25s;margin-bottom:10px;position:relative;overflow:hidden}
.bbtn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.bbtn.buy{background:linear-gradient(100deg,var(--brand),var(--brand2));color:#fff}
.bbtn.buy::after{content:'';position:absolute;inset:0;background:linear-gradient(110deg,transparent 35%,rgba(255,255,255,.35) 50%,transparent 65%);transform:translateX(-120%);animation:sweep 3.6s ease-in-out infinite}
.bbtn.dm{background:var(--card);color:var(--good);border:1.5px solid var(--good)}
.bbtn:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(37,99,235,.3)}
.bbtn.dm:hover{background:var(--good);color:#fff;box-shadow:0 12px 24px rgba(22,163,74,.3)}
.spec{margin:14px 0 0;border-top:1px solid var(--line);padding-top:12px;display:grid;gap:8px;font-size:13px}
.spec li{display:flex;justify-content:space-between;gap:10px}
.spec span{color:var(--mut)}
.feat{margin-top:12px;border-top:1px solid var(--line);padding-top:12px;display:grid;gap:8px;font-size:13px}
.feat li{display:flex;gap:9px;align-items:flex-start}
.feat svg{width:16px;height:16px;flex-shrink:0;margin-top:2px;fill:none;stroke:var(--good);stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.trust{display:grid;gap:8px;font-size:12.5px;color:var(--mut);padding:16px 18px}
.trust span{display:flex;gap:9px;align-items:center}
.trust svg{width:16px;height:16px;fill:none;stroke:var(--brand);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.share{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:22px;font-weight:700;font-size:14px}
.share a,.share button{display:inline-flex;align-items:center;gap:7px;background:var(--card);border:1px solid var(--line);padding:8px 14px;border-radius:999px;font-size:13px;font-weight:600;transition:all .2s var(--ease)}
.share a:hover,.share button:hover{background:var(--brand);color:#fff;border-color:var(--brand);transform:translateY(-2px)}
.share svg{width:15px;height:15px;fill:currentColor}
#related{margin-top:34px}
#related .sec-h{text-align:left}
.nf{text-align:center;padding:70px 20px}
.nf h1{font:800 96px/1 var(--font);color:var(--brand)}
.nf p{color:var(--mut);margin:10px 0 24px}

/* ---------- footer ---------- */
.site-footer{background:var(--foot);color:#d6dae3;margin-top:34px}
.f-top{display:grid;grid-template-columns:1.6fr 1fr 1fr;gap:40px;padding:34px 0 26px}
.site-footer .logo .lt{color:#fff}
.site-footer .logo small{color:#9aa1b0}
.f-about{font-size:13px;margin:14px 0 16px;color:#cdd2dc}
.f-form{display:flex;gap:10px;max-width:420px}
.f-form input{flex:1;min-width:0;background:#2a2d33;border:1px solid #373b44;border-radius:6px;padding:11px 14px;color:#fff;font-size:13px;outline:0;transition:border-color .2s}
.f-form input:focus{border-color:var(--brand)}
.f-form button{background:var(--brand);color:#fff;font-weight:600;font-size:13px;padding:11px 24px;border-radius:6px;transition:transform .2s,filter .2s}
.f-form button:hover{transform:translateY(-2px);filter:brightness(1.12)}
.f-note{font-size:11px;color:#8a909d;margin:10px 0 18px;font-style:italic}
.f-soc{display:flex;gap:10px}
.f-soc a{width:34px;height:34px;border-radius:6px;background:#2f333b;display:grid;place-items:center;color:#fff;transition:all .25s var(--ease)}
.f-soc a:hover{background:var(--brand);transform:translateY(-4px)}
.f-soc svg{width:15px;height:15px;fill:currentColor}
.f-col h4{font:700 14.5px var(--font);color:#fff;padding-bottom:10px;margin-bottom:14px;border-bottom:1px solid #3a3e47}
.f-col ul{display:grid;gap:14px;font-size:12px}
.f-col a{color:#c3c8d3;transition:color .2s,padding .2s}
.f-col a:hover{color:#fff;padding-left:5px}
.f-bot{background:#17191d;font-size:11.5px;color:#c3c8d3}
.f-bot .wrap{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:14px;padding-bottom:14px}
.fab{position:fixed;right:16px;bottom:20px;width:54px;height:54px;border-radius:50%;background:#16a34a;color:#fff;display:grid;place-items:center;z-index:250;box-shadow:0 10px 24px rgba(22,163,74,.5);animation:ring 2.8s infinite;transition:transform .25s var(--ease)}
.fab:hover{transform:scale(1.1) rotate(-6deg)}
.fab svg{width:26px;height:26px;fill:currentColor}
.toasts{position:fixed;left:50%;bottom:26px;transform:translateX(-50%);z-index:800;display:grid;gap:8px;justify-items:center;pointer-events:none;width:max-content;max-width:92vw}
.toast{display:flex;align-items:center;gap:10px;background:var(--card);border:1px solid var(--line);color:var(--ink);padding:12px 18px;border-radius:12px;box-shadow:var(--sh-h);font-size:13.5px;font-weight:600;animation:toastIn .45s var(--ease) both;transition:opacity .4s,transform .4s}
.toast svg{width:18px;height:18px;fill:none;stroke:#22c55e;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.toast.out{opacity:0;transform:translateY(10px)}

/* ---------- skeleton + reveal + tilt ---------- */
.sk{position:relative;overflow:hidden;background:var(--line);border-radius:8px}
.sk::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.4),transparent);transform:translateX(-100%);animation:shimmer 1.4s infinite}
.sk-card{border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--card)}
.sk-card .sk{border-radius:0}
.reveal{opacity:0;translate:0 20px;transition:opacity .55s ease,translate .55s var(--ease),box-shadow .3s,border-color .3s,transform .2s ease-out}
.reveal.in{opacity:1;translate:0 0;transition:opacity .55s ease,translate .45s var(--ease),box-shadow .3s,border-color .3s,transform .18s ease-out}
.tilt.reveal,.tilt.reveal.in{transform:perspective(1000px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg))}
.pcard.reveal.in:hover{translate:0 -6px}

/* ---------- motion ---------- */
@keyframes popIn{from{transform:scale(.3) rotate(-120deg);opacity:0}to{transform:none;opacity:1}}
@keyframes rise{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes blob{0%,100%{transform:translate(0,0) scale(1)}33%{transform:translate(30px,-24px) scale(1.08)}66%{transform:translate(-22px,18px) scale(.94)}}
@keyframes twinkle{0%,100%{opacity:.25;transform:scale(.8)}50%{opacity:1;transform:scale(1.2)}}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
@keyframes blink{50%{opacity:0}}
@keyframes waveMove{to{transform:translateX(-50%)}}
@keyframes shimmer{to{transform:translateX(100%)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes sweep{0%,55%{transform:translateX(-120%)}85%,100%{transform:translateX(120%)}}
@keyframes slideX{from{width:20px}to{width:64px}}
@keyframes ring{0%{box-shadow:0 0 0 0 rgba(22,163,74,.55)}70%{box-shadow:0 0 0 16px rgba(22,163,74,0)}100%{box-shadow:0 0 0 0 rgba(22,163,74,0)}}
@keyframes toastIn{from{opacity:0;transform:translateY(24px) scale(.96)}to{opacity:1;transform:none}}

/* ---------- home visibility ---------- */
#home{display:none}
.is-home #home{display:block}
.is-home .inner{display:none}

/* ---------- responsive ---------- */
@media(max-width:1100px){
  .pgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .pd{grid-template-columns:1fr}
  .pd-side{position:static}
  .page-grid{grid-template-columns:1fr}
  .side{position:static}
  .wgrid{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:18px}
  .wi:nth-child(3){border-left:0}
  .f-top{grid-template-columns:1fr 1fr}
  .f-top>div:first-child{grid-column:1/-1}
}
@media(max-width:900px){
  .nav,.aff,.hide-m{display:none}
  .burger{display:grid}
  .actions{margin-left:auto}
  .hero-in{grid-template-columns:1fr;gap:26px;padding-top:40px;padding-bottom:120px}
  .promo{max-width:560px}
}
@media(max-width:620px){
  .wrap{padding:0 14px}
  .bar{height:60px;gap:10px}
  .logo .lt{font-size:19px}
  .pgrid{grid-template-columns:1fr;gap:18px}
  .promo{grid-template-columns:1fr;padding:22px}
  .illus{max-width:200px;justify-self:center}
  .wgrid{grid-template-columns:1fr}
  .wi{border-left:0;border-top:1px solid rgba(37,99,235,.18);padding:12px 4px}
  .wi:first-child{border-top:0}
  .f-top{grid-template-columns:1fr;gap:26px}
  .f-bot .wrap{flex-direction:column;text-align:center}
  .pname{padding:0 62px;font-size:21px}
  .post-body{font-size:16px}
  .toasts{bottom:90px}
  .wave.front{height:70px}.wave.back{height:90px}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
  .reveal{opacity:1;translate:0 0}
}
@media print{
  .site-header,.hero,.side,.site-footer,.fab,.share,#related,.pd-side,.toasts{display:none!important}
  .pd{display:block}
  body{background:#fff;color:#000}
}

