var CHEV='<svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>';

/* ---------- helpers ---------- */
var $=function(s,c){return(c||document).querySelector(s)};
var $$=function(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))};
var REDUCED=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
var FINE=!!(window.matchMedia&&matchMedia('(hover:hover) and (pointer:fine)').matches);
var YEAR=new Date().getFullYear();
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function lbl(l){return '/search/label/'+encodeURIComponent(l)}
function yr(s){return String(s).replace(/\{year\}/g,YEAR)}
function fmt(d){try{return new Date(d).toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'})}catch(e){return ''}}
function icon(k){return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[k]||'')+'</svg>'}
function toast(msg){
  var box=$('#toasts');if(!box)return;
  var t=document.createElement('div');t.className='toast';
  t.innerHTML='<svg viewBox="0 0 24 24"><path d="M5 12l5 5 9-10"/></svg><span>'+esc(msg)+'</span>';
  box.appendChild(t);
  setTimeout(function(){t.classList.add('out');setTimeout(function(){t.remove()},450)},3200);
}
var PH='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="640" height="400"><rect width="640" height="400" fill="#e8ecf6"/><rect x="40" y="40" width="560" height="30" rx="6" fill="#d3d9ea"/><rect x="40" y="90" width="360" height="270" rx="8" fill="#d3d9ea"/><rect x="420" y="90" width="180" height="120" rx="8" fill="#dfe4f2"/></svg>');
function szW(u,w){
  if(!u)return PH;
  return u.replace(/\/s\d+(-[a-z]+)*\//,'/w'+w+'/').replace(/=s\d+(-[a-z]+)*(?=$|\?)/,'=w'+w);
}
var PAL=[['#f6d5f7','#c9e4ff','#2a2a3c'],['#fff1c9','#ffd6a5','#3a2a12'],['#d4f0ff','#e3d9ff','#1d2b4f'],['#ffd9e6','#d9e4ff','#3a1d3a'],['#d6f5e3','#d4ecff','#123a2a'],['#e5e7ee','#c9cdda','#2a2d3a']];
function pal(t){var h=0;for(var i=0;i<t.length;i++)h=(h*31+t.charCodeAt(i))>>>0;return PAL[h%PAL.length]}
function shortName(t){return t.split(/\s[–—-]\s/)[0].trim()}

/* ---- product data lives in the post body as a hidden comment or span ----
   <!--tpl price=10.50 old=15 demo=https://... buy=https://... sales=426 rating=4.9 reviews=221 author="Wire Templates" features="SEO ready|Fast|Responsive" version=1.2 -->
*/
function kv(str,m){
  str.replace(/([\w-]+)\s*=\s*("([^"]*)"|'([^']*)'|[^\s]+)/g,function(_,k,raw,a,b){
    var v=(a!==undefined&&a!==''||raw.charAt(0)==='"')?a:(b!==undefined&&b!==''||raw.charAt(0)==="'")?b:raw;
    m[k.toLowerCase()]=String(v==null?'':v).replace(/&amp;/g,'&');
  });
}
function norm(m){
  function n(v){var x=parseFloat(v);return isNaN(x)?null:x}
  return{
    price:(m.price===undefined||m.price==='')?null:(/^free$/i.test(m.price)?0:n(m.price)),
    old:n(m.old),demo:m.demo||'',buy:m.buy||'',download:m.download||'',
    sales:n(m.sales),rating:n(m.rating),reviews:n(m.reviews),
    author:m.author||'',name:m.name||'',badge:m.badge||'',
    version:m.version||'',updated:m.updated||'',license:m.license||'',
    features:m.features?m.features.split('|').map(function(x){return x.trim()}).filter(Boolean):[]
  };
}
function readMeta(html){
  var m={},c=html.match(/<!--\s*tpl\b([\s\S]*?)-->/i);
  if(c)kv(c[1],m);
  var s=html.match(/<(?:span|div)[^>]*class=["'][^"']*\btpl\b[^"']*["'][^>]*>/i);
  if(s)s[0].replace(/data-([\w-]+)=["']([^"']*)["']/g,function(_,k,v){m[k.toLowerCase()]=v});
  return norm(m);
}
function priceLabel(p){
  if(p===null||p===undefined)return '';
  if(p===0)return 'Free';
  var s=p.toFixed(2).replace(/\.00$/,'');
  return CFG.currency+s;
}

function parse(e){
  var lk=(e.link||[]).filter(function(l){return l.rel==='alternate'})[0];
  var html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
  var m=html.match(/<img[^>]+src=["']([^"']+)/i);
  var img=e.media$thumbnail?e.media$thumbnail.url:(m?m[1]:'');
  var text=html.replace(/<!--[\s\S]*?-->/g,' ').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
  return{
    title:e.title.$t,url:lk?lk.href:'#',iso:e.published.$t,updated:e.updated?e.updated.$t:e.published.$t,
    date:fmt(e.published.$t),author:(e.author&&e.author[0])?e.author[0].name.$t:'Admin',
    cats:(e.category||[]).map(function(c){return c.term}),img:img,
    excerpt:text.slice(0,160),meta:readMeta(html)
  };
}
var memo={};
function getFeed(label,max,start,extra){
  extra=extra||{};
  var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+max+'&start-index='+(start||1)+(extra.q?'&q='+encodeURIComponent(extra.q):'')+(extra.path?'&path='+encodeURIComponent(extra.path):'');
  if(memo[u])return memo[u];
  return memo[u]=fetch(u).then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
    var f=j.feed||{};
    return{total:+((f.openSearch$totalResults||{}).$t||0),posts:(f.entry||[]).map(parse)};
  });
}
function ld(o){var s=document.createElement('script');s.type='application/ld+json';s.text=JSON.stringify(o);document.head.appendChild(s)}

var io=('IntersectionObserver' in window)?new IntersectionObserver(function(es){
  es.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target);(function(t){setTimeout(function(){t.style.transitionDelay=''},1400)})(en.target)}});
},{threshold:.06}):null;
function reveal(root){
  $$('.reveal:not(.in)',root).forEach(function(el,i){
    el.style.transitionDelay=Math.min(i*70,350)+'ms';
    if(io)io.observe(el);else el.classList.add('in');
  });
}

/* ---------- product cards ---------- */
function stars(m){
  if(!m.rating)return '';
  return '<span class="st" style="--r:'+m.rating+'" role="img" aria-label="Rated '+m.rating+' out of 5">★★★★★</span>'+(m.reviews?'<small>('+m.reviews+')</small>':'');
}
function pcard(p,best){
  var g=pal(p.title),m=p.meta,pr=priceLabel(m.price),buy=m.buy||m.download||p.url;
  return '<article class="pcard tilt reveal">'+
    '<a class="pv" href="'+esc(p.url)+'" style="--g1:'+g[0]+';--g2:'+g[1]+';--fg:'+g[2]+'" aria-label="'+esc(p.title)+'">'+
      (pr?'<span class="price'+(m.price===0?' free':'')+'">'+pr+'</span>':'')+
      (m.badge?'<span class="tag">'+esc(m.badge)+'</span>':'')+
      '<span class="pname">'+esc(m.name||shortName(p.title))+'</span>'+
      '<span class="frame"><img loading="lazy" width="640" height="400" alt="" src="'+esc(szW(p.img,640))+'"/></span>'+
      '<span class="vd">View Details</span></a>'+
    '<div class="pb"><h3><a href="'+esc(p.url)+'">'+esc(p.title)+'</a></h3>'+
    (best?'<div class="by">By - '+esc(m.author||p.author)+'</div><div class="tg">'+esc(p.cats[0]||'')+'</div>':
    '<div class="pr"><div class="rt"><div class="l1">'+(stars(m)||'<small>'+esc(p.date)+'</small>')+'</div>'+(m.sales?'<small>'+Number(m.sales).toLocaleString()+' Sales</small>':'')+'</div>'+
    '<div class="pa"><a class="cart" href="'+esc(buy)+'" aria-label="Get this template"'+(m.buy||m.download?' target="_blank" rel="noopener"':'')+'>'+CART+'</a>'+
    (m.demo?'<a class="demo" href="'+esc(m.demo)+'" target="_blank" rel="noopener">'+EYE+'Demo</a>':'')+'</div></div>')+
    '</div></article>';
}
function skelCards(n){
  var s='';for(var i=0;i<n;i++)s+='<div class="sk-card"><div class="sk" style="aspect-ratio:16/9.6"></div><div style="padding:14px"><div class="sk" style="height:14px;width:80%"></div><div class="sk" style="height:12px;width:45%;margin-top:12px"></div></div></div>';
  return s;
}

/* ---------- header, menu, theme, scroll ---------- */
function splitHero(){}
function initChrome(){
  document.documentElement.style.setProperty('--cols',Math.max(2,Math.min(4,CFG.layout.columns)));
  $('#logoSub').textContent=CFG.logoSub;$('#logoSub2').textContent=CFG.logoSub;
  var path=decodeURIComponent(location.pathname);
  $('#nav').innerHTML=CFG.menu.map(function(m){
    var cur=m.u&&((m.u==='/'&&path==='/')||(m.u!=='/'&&path===m.u));
    var a='<a href="'+esc(m.u||(m.sub?m.sub[0][1]:'#'))+'"'+(cur?' class="cur"':'')+'>'+esc(m.t)+(m.sub?CHEV:'')+'</a>';
    return '<div class="nv">'+a+(m.sub?'<div class="sub">'+m.sub.map(function(s){return '<a href="'+esc(s[1])+'">'+esc(s[0])+'</a>'}).join('')+'</div>':'')+'</div>';
  }).join('');
  $('#dnav').innerHTML=CFG.menu.map(function(m){
    var h='<a href="'+esc(m.u||'#')+'">'+esc(m.t)+'</a>';
    if(m.sub)h='<a href="#" onclick="return false" style="color:var(--mut);font-size:12px;letter-spacing:1px;text-transform:uppercase;border:0">'+esc(m.t)+'</a><div class="ds">'+m.sub.map(function(s){return '<a href="'+esc(s[1])+'">'+esc(s[0])+'</a>'}).join('')+'</div>';
    return h;
  }).join('')+'<a href="'+esc(CFG.affiliate.url)+'" style="color:var(--brand)">'+esc(CFG.affiliate.text)+'</a>';
  $('#affBtn').href=CFG.affiliate.url;$('#affTxt').textContent=CFG.affiliate.text;

  /* footer */
  var F=CFG.footer;
  $('#fAbout').textContent=F.about;$('#fNote').textContent=F.note;$('#yr').textContent=YEAR;
  [$('#fc1'),$('#fc2')].forEach(function(el,i){
    var c=F.cols[i];if(!c){el.style.display='none';return}
    el.innerHTML='<h4>'+esc(c.title)+'</h4><ul>'+c.links.map(function(l){return '<li><a href="'+esc(l[1])+'">'+esc(l[0])+'</a></li>'}).join('')+'</ul>';
  });
  $('#fsoc').innerHTML=CFG.social.map(function(s){return '<a href="'+esc(s[1])+'" aria-label="'+esc(s[2])+'" rel="noopener" target="_blank">'+icon(s[0])+'</a>'}).join('');
  var fab=$('#fab');if(CFG.chat.url){fab.href=CFG.chat.url;fab.setAttribute('aria-label',CFG.chat.label)}else fab.style.display='none';

  var nf=$('#newsForm');
  if(CFG.newsletterAction)nf.action=CFG.newsletterAction;
  nf.addEventListener('submit',function(e){
    var v=$('#newsEmail').value.trim();
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)){e.preventDefault();toast('Please enter a valid email address');return}
    if(!CFG.newsletterAction){e.preventDefault();location.href='mailto:'+CFG.contactEmail+'?subject='+encodeURIComponent('Subscribe me')+'&body='+encodeURIComponent('Please add this email to your list: '+v)}
    toast('Thank you for following!');nf.reset();
  });

  var drawer=$('#drawer'),scrim=$('#scrim');
  function dset(o){drawer.classList.toggle('open',o);scrim.classList.toggle('open',o)}
  $('#bbtn').onclick=function(){dset(true)};
  $('#dclose').onclick=scrim.onclick=function(){dset(false)};
  $$('a',drawer).forEach(function(a){a.addEventListener('click',function(){if(a.getAttribute('href')!=='#')dset(false)})});

  var root=document.documentElement,tico=$('#tico');
  function paint(){tico.innerHTML=root.getAttribute('data-theme')==='dark'?ICONS.sun:ICONS.moon}
  function flip(e){if(e)e.preventDefault();var d=root.getAttribute('data-theme')==='dark'?'light':'dark';if(d==='dark')root.setAttribute('data-theme','dark');else root.removeAttribute('data-theme');try{localStorage.setItem('tm-theme',d)}catch(x){}paint()}
  paint();$('#tbtn').onclick=flip;$('#dtheme').onclick=flip;

  var hdr=$('#hdr'),rp=$('#rp'),pb=$('#postBody');
  function onScroll(){
    hdr.classList.toggle('scrolled',window.scrollY>10);
    if(pb&&document.body.classList.contains('is-item')){var r=pb.getBoundingClientRect(),tot=r.height-window.innerHeight*.5;rp.style.width=Math.max(0,Math.min(100,(-r.top/Math.max(tot,1))*100))+'%'}
  }
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();

  /* card spotlight / tilt */
  if(!REDUCED&&FINE){
    document.addEventListener('pointermove',function(e){
      if(!e.target.closest)return;
      var s=e.target.closest('.tilt');if(!s)return;
      var r=s.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;
      s.style.setProperty('--ry',((px/r.width-.5)*6).toFixed(2)+'deg');
      s.style.setProperty('--rx',((.5-py/r.height)*5).toFixed(2)+'deg');
    },{passive:true});
    document.addEventListener('pointerout',function(e){
      var s=e.target.closest&&e.target.closest('.tilt');
      if(s&&!s.contains(e.relatedTarget)){s.style.setProperty('--rx','0deg');s.style.setProperty('--ry','0deg')}
    });
  }
}

/* ---------- search: overlay + hero live results ---------- */
function liveResults(q,box,mode,done){
  getFeed('',6,1,{q:q}).then(function(r){
    box.innerHTML=r.posts.length?r.posts.map(function(p){
      var pr=priceLabel(p.meta.price);
      return '<a href="'+esc(p.url)+'"><img alt="" loading="lazy" src="'+esc(szW(p.img,160))+'"/><span>'+esc(p.title)+'</span>'+(pr?'<b>'+pr+'</b>':'')+'</a>';
    }).join(''):'<em>No templates found.</em>';
    if(done)done();
  }).catch(function(){box.innerHTML=''});
}
function initSearch(){
  var sov=$('#sov'),inp=$('#sinput'),res=$('#sres'),t,t2,hq=$('#hq'),hd=$('#hdrop');
  function close(){sov.classList.remove('open')}
  $('#sbtn').onclick=function(){sov.classList.add('open');setTimeout(function(){inp.focus()},250)};
  $('#sclose').onclick=close;
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){close();hd.classList.remove('show');$('#drawer').classList.remove('open');$('#scrim').classList.remove('open')}
    var tag=(e.target.tagName||'').toLowerCase();
    if(e.key==='/'&&tag!=='input'&&tag!=='textarea'){e.preventDefault();$('#sbtn').click()}
  });
  document.addEventListener('click',function(e){if(!$('#hform').contains(e.target))hd.classList.remove('show')});
  inp.addEventListener('input',function(){clearTimeout(t);var q=inp.value.trim();if(q.length<2){res.innerHTML='';return}t=setTimeout(function(){liveResults(q,res)},300)});
  hq.addEventListener('input',function(){clearTimeout(t2);var q=hq.value.trim();if(q.length<2){hd.classList.remove('show');return}t2=setTimeout(function(){liveResults(q,hd,0,function(){hd.classList.add('show')})},300)});
}

/* ---------- home ---------- */
function initHome(){
  if(!$('#home')||!document.body.classList.contains('is-home'))return;
  var H=CFG.hero;
  $('#heroT').textContent=yr(H.title);
  $('#heroS').textContent=H.text;
  $('#hq').placeholder=H.placeholder;
  $('#popular').innerHTML=esc(H.popularLabel)+' '+H.popular.map(function(p,i){return '<a href="/search?q='+encodeURIComponent(p)+'">'+esc(p)+'</a>'+(i<H.popular.length-1?' ,':'')}).join('');
  $('#exTitle').textContent=CFG.explore.title;$('#exSub').textContent=CFG.explore.sub;

  /* filters + grid + load more */
  var grid=$('#grid'),more=$('#moreBtn'),pills=$('#pills'),per=CFG.layout.perPage,state={label:'',start:1,total:0,busy:false};
  pills.innerHTML=[CFG.allLabel].concat(CFG.filters).map(function(f,i){return '<button class="pill'+(i===0?' on':'')+'" role="tab" aria-selected="'+(i===0)+'" data-l="'+(i===0?'':esc(f))+'">'+esc(f)+'</button>'}).join('');
  function load(reset){
    if(state.busy)return;state.busy=true;more.classList.add('loading');
    if(reset){grid.classList.add('fade');grid.innerHTML=skelCards(Math.min(per,CFG.layout.columns*2));state.start=1;more.parentNode.style.display='none'}
    getFeed(state.label,per,state.start).then(function(r){
      state.total=r.total;
      if(reset)grid.innerHTML='';
      if(!r.posts.length&&reset)grid.innerHTML='<div class="empty">No templates found'+(state.label?' for “'+esc(state.label)+'”':'')+'. Add the label to your posts to show them here.</div>';
      grid.insertAdjacentHTML('beforeend',r.posts.map(function(p){return pcard(p)}).join(''));
      state.start+=per;reveal(grid);
      more.parentNode.style.display=(state.start>state.total||r.posts.length<per)?'none':'flex';
    }).catch(function(){grid.innerHTML='<div class="empty">Could not load templates right now.</div>';more.parentNode.style.display='none'})
    .then(function(){state.busy=false;more.classList.remove('loading');grid.classList.remove('fade')});
  }
  pills.addEventListener('click',function(e){
    var b=e.target.closest&&e.target.closest('.pill');if(!b)return;
    $$('.pill',pills).forEach(function(x){x.classList.remove('on');x.setAttribute('aria-selected','false')});
    b.classList.add('on');b.setAttribute('aria-selected','true');
    state.label=b.getAttribute('data-l')||'';load(true);
  });
  more.onclick=function(){load(false)};
  load(true);

  /* best sellers */
  if(CFG.layout.showBest){
    var sec=$('#best'),bg=$('#bestGrid'),n=CFG.layout.bestCount;
    $('#bestT').textContent=yr(CFG.bestTitle);
    getFeed(CFG.bestLabel,n).then(function(r){
      if(r.posts.length)return r.posts;
      return getFeed('',30).then(function(a){
        var p=a.posts.filter(function(x){return x.meta.sales>0}).sort(function(x,y){return y.meta.sales-x.meta.sales});
        return p.slice(0,n);
      });
    }).then(function(p){
      if(!p.length)return;
      sec.style.display='block';
      bg.innerHTML=p.map(function(x){return pcard(x,true)}).join('');reveal(bg);
    }).catch(function(){});
  }

  ld({'@context':'https://schema.org','@type':'WebSite',name:document.title,url:location.origin+'/',potentialAction:{'@type':'SearchAction',target:location.origin+'/search?q={search_term_string}','query-input':'required name=search_term_string'}});
}

/* ---------- label / search pages: product grid with Load More ---------- */
function initArchive(){
  var b=document.body;
  if(!b.classList.contains('is-index')||b.classList.contains('is-home'))return;
  var grid=$('#archGrid');if(!grid)return;
  var p=decodeURIComponent(location.pathname),m=p.match(/^\/search\/label\/(.+)$/),label=m?m[1]:'',q=new URLSearchParams(location.search).get('q')||'';
  if(!m&&p!=='/search')return;
  var per=CFG.layout.perPage+3,start=1,total=0,busy=false,btn=$('#archMore'),wrap=$('#archMoreWrap'),ssr=grid.innerHTML;
  function load(first){
    if(busy)return;busy=true;btn.classList.add('loading');
    getFeed(label,per,start,{q:q}).then(function(r){
      total=r.total;
      if(first)grid.innerHTML='';
      if(!r.posts.length&&first){grid.innerHTML=ssr;throw 0}
      grid.insertAdjacentHTML('beforeend',r.posts.map(function(x){return pcard(x)}).join(''));
      start+=per;reveal(grid);$('#archPager').style.display='none';
      wrap.style.display=(start>total||r.posts.length<per)?'none':'flex';
    }).catch(function(){}).then(function(){busy=false;btn.classList.remove('loading')});
  }
  btn.onclick=function(){load(false)};
  grid.innerHTML=skelCards(Math.min(6,CFG.layout.columns*2));
  load(true);
}

/* ---------- inner pages: breadcrumbs, product page ---------- */
function bodyMeta(body){
  var m={},w=document.createTreeWalker(body,NodeFilter.SHOW_COMMENT,null,false),n;
  while((n=w.nextNode())){if(/^\s*tpl\b/i.test(n.nodeValue)){kv(n.nodeValue.replace(/^\s*tpl\b/i,''),m);break}}
  var s=$('.tpl',body);
  if(s)for(var i=0;i<s.attributes.length;i++){var a=s.attributes[i];if(a.name.indexOf('data-')===0)m[a.name.slice(5)]=a.value}
  return norm(m);
}
function initPost(){
  var body=$('#postBody');if(!body)return;
  var isItem=document.body.classList.contains('is-item'),h1=$('.post-title');
  var cr=$('#crumbs'),la=$('.chips a'),parts=['<a href="/">Home</a>'];
  if(la)parts.push('<a href="'+esc(la.getAttribute('href'))+'">'+esc(la.textContent)+'</a>');
  parts.push('<span>'+esc(h1?h1.textContent:'')+'</span>');
  if(cr)cr.innerHTML=parts.join('<span class="sep">›</span>');
  $$('img',body).forEach(function(im,i){if(i>0)im.setAttribute('loading','lazy');im.setAttribute('decoding','async')});
  if(!isItem)return;

  var m=bodyMeta(body),title=h1?h1.textContent:document.title;

  /* preview frame: move the first image to the top */
  var img=$('img',body);
  if(img){
    var big=img.src.replace(/\/s\d+(-[a-z]+)*\//,'/s1600/').replace(/\/w\d+(-h\d+)?(-[a-z]+)?\//,'/s1600/');
    $('#preview').innerHTML='<div class="pframe"><div class="win"><div class="tb"><i></i><i></i><i></i></div><img alt="'+esc(title)+'" src="'+esc(big)+'" fetchpriority="high"/></div></div>';
    var host=img.closest('.separator,.tr-caption-container')||(img.parentNode&&img.parentNode.tagName==='A'?img.parentNode:img);
    if(host&&host!==body)host.parentNode.removeChild(host);
  }else $('#preview').style.display='none';

  /* buy box */
  var free=m.price===0,price=priceLabel(m.price),buy=m.buy||m.download||'',disc=(m.old&&m.price&&m.old>m.price)?Math.round((1-m.price/m.old)*100):0;
  var spec=[];
  if(m.version)spec.push(['Version',m.version]);
  if(m.updated)spec.push(['Last update',m.updated]);
  spec.push(['License',m.license||CFG.license]);
  if(m.author)spec.push(['Author',m.author]);
  if(m.sales)spec.push(['Sales',Number(m.sales).toLocaleString()]);
  var h='<div class="card bb">';
  if(price)h+='<div class="bp"><span class="now">'+price+'</span>'+(m.old&&!free?'<s class="old">'+CFG.currency+m.old+'</s>':'')+(disc?'<span class="off">-'+disc+'%</span>':'')+'</div>';
  if(m.rating)h+='<div class="rt">'+stars(m)+'<small>'+m.rating+' / 5</small></div>';else h+='<div style="height:14px"></div>';
  if(buy)h+='<a class="bbtn buy" href="'+esc(buy)+'" target="_blank" rel="noopener">'+CART+(free?CFG.freeText:CFG.buyText)+'</a>';
  else h+='<a class="bbtn buy" href="/p/contact.html">'+CART+'Contact us to get this</a>';
  if(m.demo)h+='<a class="bbtn dm" href="'+esc(m.demo)+'" target="_blank" rel="noopener">'+EYE+CFG.demoText+'</a>';
  h+='<ul class="spec">'+spec.map(function(s){return '<li><span>'+esc(s[0])+'</span><b>'+esc(s[1])+'</b></li>'}).join('')+'</ul>';
  if(m.features.length)h+='<ul class="feat">'+m.features.map(function(f){return '<li>'+CHECK+'<span>'+esc(f)+'</span></li>'}).join('')+'</ul>';
  h+='</div><div class="card trust">'+CFG.trust.map(function(t){return '<span><svg viewBox="0 0 24 24"><path d="M5 12l5 5 9-10"/></svg>'+esc(t)+'</span>'}).join('')+'</div>';
  $('#buybox').innerHTML=h;

  /* share */
  var u=encodeURIComponent(location.href),t=encodeURIComponent(title);
  $('#share').innerHTML='<span>Share:</span>'+
    '<a target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u='+u+'">'+icon('fb')+'Facebook</a>'+
    '<a target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?url='+u+'&amp;text='+t+'">'+icon('x')+'X</a>'+
    '<a target="_blank" rel="noopener" href="https://wa.me/?text='+t+'%20'+u+'">'+icon('wa')+'WhatsApp</a>'+
    '<button type="button" id="copyLink">'+icon('link')+'Copy link</button>';
  $('#copyLink').onclick=function(){
    var b=this;
    (navigator.clipboard?navigator.clipboard.writeText(location.href):Promise.reject()).then(function(){toast('Link copied to clipboard');b.lastChild.textContent='Copied!';setTimeout(function(){b.lastChild.textContent='Copy link'},1800)}).catch(function(){window.prompt('Copy this link:',location.href)});
  };

  /* structured data */
  var offer=(m.price!==null)?{'@type':'Offer',price:String(m.price),priceCurrency:'USD',availability:'https://schema.org/InStock',url:location.href}:undefined;
  ld({'@context':'https://schema.org','@type':'Product',name:title,image:img?[img.src]:undefined,description:(body.textContent||'').trim().slice(0,200),brand:{'@type':'Brand',name:(m.author||document.title.split(' - ').pop())},offers:offer,aggregateRating:(m.rating&&m.reviews)?{'@type':'AggregateRating',ratingValue:String(m.rating),reviewCount:String(m.reviews)}:undefined});
  if(la)ld({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:location.origin+'/'},{'@type':'ListItem',position:2,name:la.textContent,item:location.origin+la.getAttribute('href')},{'@type':'ListItem',position:3,name:title}]});

  /* related */
  if(la)getFeed(la.textContent.trim(),5,1).then(function(r){
    var p=r.posts.filter(function(x){return x.url.indexOf(location.pathname)<0}).slice(0,3);
    if(!p.length)return;
    $('#related').innerHTML='<div class="sec-h"><h2>Related Templates</h2></div><div class="pgrid">'+p.map(function(x){return pcard(x)}).join('')+'</div>';
    reveal($('#related'));
  }).catch(function(){});
}

/* hide the sidebar column when there are no widgets in it */
function initLayout(){
  var pg=$('#pageGrid'),side=$('#sidebarWrap');
  if(!pg||!side)return;
  var has=$('.widget',side);
  if(!has||document.body.classList.contains('is-item')||document.body.classList.contains('is-static_page')){side.style.display='none';pg.classList.add('nos')}
}

initChrome();initSearch();initHome();initArchive();initPost();initLayout();
})();
